using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Threading;
using TrayLeaf;
class Version091Tests {
 static int passed,failed;
 const BindingFlags Hidden=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Check(string name,bool ok){Console.WriteLine((ok?"PASS ":"FAIL ")+name);if(ok)passed++;else failed++;}
 static IEnumerable<DependencyObject> Children(DependencyObject parent){foreach(object item in LogicalTreeHelper.GetChildren(parent)){var child=item as DependencyObject;if(child==null)continue;yield return child;foreach(var nested in Children(child))yield return nested;}}
 static void Render(Window dialog,string path){dialog.UpdateLayout();var image=new RenderTargetBitmap((int)Math.Ceiling(dialog.ActualWidth),(int)Math.Ceiling(dialog.ActualHeight),96,96,PixelFormats.Pbgra32);var background=new DrawingVisual();using(var dc=background.RenderOpen())dc.DrawRectangle((Brush)dialog.FindResource("Canvas"),null,new Rect(0,0,image.PixelWidth,image.PixelHeight));image.Render(background);image.Render((Visual)dialog.Content);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(image));using(var f=File.Create(path))png.Save(f);}
 static DispatcherTimer Respond(Window shell,bool accept,bool suppress){var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(80)};timer.Tick+=delegate{var dialog=Application.Current.Windows.OfType<Window>().FirstOrDefault(x=>x!=shell&&x.IsVisible);if(dialog==null)return;var box=dialog.Tag as CheckBox;if(box!=null)box.IsChecked=suppress;dialog.DialogResult=accept;timer.Stop();};timer.Start();return timer;}
 [STAThread] static int Main(string[] args){try{
  var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};Window shell;using(var stream=typeof(AppRow).Assembly.GetManifestResourceStream("TrayLeaf.MainWindow.xaml"))shell=(Window)System.Windows.Markup.XamlReader.Load(stream);ThemeManager.Apply(shell,"0",0);shell.WindowStartupLocation=WindowStartupLocation.Manual;shell.Left=-10000;shell.Top=-10000;shell.ShowActivated=false;shell.Show();
  Check("hide-button-renamed",((Button)shell.FindName("ForgetButton")).Content.ToString()=="隐藏程序");
  var input=shell.FindName("ConfirmHideInput") as CheckBox;Check("hide-confirmation-settings-switch",input!=null&&input.Style==shell.FindResource("Switch"));
  var texts=Children(shell).OfType<TextBlock>().ToList();Check("about-technical-copy-removed",!texts.Any(t=>t.Text.Contains("本地 SQLite 数据库")||t.Text.Contains("仅负责重新启动应用，不恢复文档")));
  var thanks=texts.FirstOrDefault(t=>t.Text=="感谢每一位提出建议与反馈的使用者");Check("about-thanks-centered",thanks!=null&&thanks.TextAlignment==TextAlignment.Center);
  var update=(TextBlock)shell.FindName("UpdateStatus");Check("about-no-default-update-explanation",String.IsNullOrEmpty(update.Text)&&update.Visibility==Visibility.Collapsed);
  string source=File.ReadAllText(Path.Combine(args[1],"src","App.cs"));Check("close-warning-concise",source.Contains("请先保存工作,未保存的数据可能丢失！")&&!source.Contains("约 2.5 秒后仍运行的普通应用会自动结束"));Check("risk-access-protection-footer-removed",!source.Contains("不会绕过 Windows 自身的访问保护"));
  string path=Path.Combine(args[0],"hide.db");if(File.Exists(path))File.Delete(path);
  using(var db=new Database(path)){
   var policy=typeof(AppRow).Assembly.GetType("TrayLeaf.ConfirmationPreference");Check("independent-confirmation-policy",policy!=null);
   if(policy!=null){var required=policy.GetMethod("Required",BindingFlags.Static|BindingFlags.NonPublic);var remember=policy.GetMethod("Remember",BindingFlags.Static|BindingFlags.NonPublic);foreach(string key in new[]{"confirmHide","confirmForce"}){Check(key+"-default-on",(bool)required.Invoke(null,new object[]{db,key}));remember.Invoke(null,new object[]{db,key,false,true});Check(key+"-cancel-keeps-warning",(bool)required.Invoke(null,new object[]{db,key}));remember.Invoke(null,new object[]{db,key,true,false});Check(key+"-unchecked-keeps-warning",(bool)required.Invoke(null,new object[]{db,key}));remember.Invoke(null,new object[]{db,key,true,true});Check(key+"-accepted-optout-persists",!(bool)required.Invoke(null,new object[]{db,key}));db.Set(key,"1");Check(key+"-settings-reenable",(bool)required.Invoke(null,new object[]{db,key}));}Check("close-warning-independent",db.Get("confirmClose","1")=="1");}
   db.Set("confirmHide","0");var picked=new AppRow{Name="Selected",ProcessName="Selected.exe",Path=Path.Combine(args[0],"Selected.exe"),Selected=true,Args="--keep",Admin=true};var other=new AppRow{Name="Other",ProcessName="Other.exe",Path=Path.Combine(args[0],"Other.exe"),Selected=false};File.WriteAllText(picked.Path,"not an executable; must not be touched");db.SaveManaged(picked.Path,picked.Name,picked.Args,true,true);
   var rows=new List<AppRow>{picked,other};var c=new Controller(app,shell,db,true);typeof(Controller).GetField("current",Hidden).SetValue(c,rows);var grid=(DataGrid)shell.FindName("ProcessGrid");HistoryPresentation.Configure(grid);grid.ItemsSource=rows;var timer=Respond(shell,false,false);typeof(Controller).GetMethod("Forget",Hidden).Invoke(c,null);timer.Stop();
   Check("hide-acts-on-current-checked-rows",db.HiddenPrograms().Count==1&&db.HiddenPrograms()[0].Path==picked.Path);Check("unchecked-program-remains-visible",grid.Items.OfType<AppRow>().Count()==1&&grid.Items.OfType<AppRow>().First().Path==other.Path);Check("hiding-preserves-executable",File.ReadAllText(picked.Path)=="not an executable; must not be touched");Check("hiding-preserves-arguments-and-admin",db.Query("SELECT args,admin,chosen FROM managed WHERE path=?",picked.Path).Any(r=>r[0]=="--keep"&&r[1]=="1"&&r[2]=="0"));Check("hidden-selection-cleared",!picked.Selected);Check("hide-status-uses-consistent-wording",((TextBlock)shell.FindName("StatusText")).Text.StartsWith("已隐藏 1"));
   timer=Respond(shell,false,false);typeof(Controller).GetMethod("Forget",Hidden).Invoke(c,null);timer.Stop();Check("empty-selection-does-not-hide-others",db.HiddenPrograms().Count==1&&((TextBlock)shell.FindName("StatusText")).Text=="请先勾选要隐藏的程序");
   var optional=typeof(Controller).GetMethod("AskOptional",Hidden);Check("controller-shares-confirmation-persistence",optional!=null);
   if(optional!=null){foreach(var pair in new[]{new[]{"confirmHide","ConfirmHideInput"},new[]{"confirmForce","ConfirmForceInput"}}){db.Set(pair[0],"1");timer=Respond(shell,false,true);bool accepted=(bool)optional.Invoke(c,new object[]{"TEST","确认",pair[0],pair[1]});timer.Stop();Check(pair[0]+"-cancel-no-persist",!accepted&&db.Get(pair[0],"1")=="1");timer=Respond(shell,true,true);accepted=(bool)optional.Invoke(c,new object[]{"TEST","确认",pair[0],pair[1]});timer.Stop();Check(pair[0]+"-accept-syncs-setting",accepted&&db.Get(pair[0],"1")=="0"&&((CheckBox)shell.FindName(pair[1])).IsChecked==false);}}
   db.RestorePrograms(new[]{picked});Check("hidden-management-can-restore",db.FilterVisible(rows).Count==2);
  }
  var build=typeof(ModernDialog).GetMethod("Build",BindingFlags.Static|BindingFlags.NonPublic);foreach(string theme in new[]{"0","1"}){ThemeManager.Apply(shell,theme,0);foreach(string kind in new[]{"隐藏所选程序","系统 / 服务进程风险提醒"}){var dialog=(Window)build.Invoke(null,new object[]{shell,kind=="隐藏所选程序"?"将隐藏 3 个程序\n\n隐藏只影响程序列表，不会关闭或卸载应用，可在设置中恢复显示":"继续可能导致服务中断、黑屏、注销或系统崩溃；是否仍然继续？",kind,true,true});dialog.WindowStartupLocation=WindowStartupLocation.Manual;dialog.Left=-10000;dialog.Top=-10000;dialog.ShowActivated=false;dialog.Show();dialog.UpdateLayout();var top=(Grid)dialog.Content;Check(kind+"-no-caption-theme-"+theme,!Children(top.Children[0]).OfType<TextBlock>().Any());Check(kind+"-body-title-retained-theme-"+theme,Children(top.Children[1]).OfType<TextBlock>().Any(t=>t.Text==kind));var box=(CheckBox)dialog.Tag;Check(kind+"-optout-visible-themed-"+theme,box.Content.ToString()=="不再提示"&&box.ActualWidth>75&&box.Foreground==dialog.FindResource("Text"));var yes=Children(dialog).OfType<Button>().First(b=>(b.Content as string)=="确认继续");Check(kind+"-controls-separated-"+theme,box.TranslatePoint(new Point(box.ActualWidth,0),dialog).X<yes.TranslatePoint(new Point(),dialog).X);Render(dialog,Path.Combine(args[0],(kind=="隐藏所选程序"?"hide":"risk")+"-theme-"+theme+".png"));dialog.Close();}}
  var manager=new ProgramSelectionDialog(shell,new List<AppRow>(),true);var root=(Grid)manager.Content;Check("resizable-dialog-no-caption",!Children(root.Children[0]).OfType<TextBlock>().Any());Check("resizable-dialog-close-retained",Children(root.Children[0]).OfType<Button>().Any(b=>b.Name=="DialogCloseButton"));manager.Close();shell.Close();
 }catch(Exception e){failed++;Console.Error.WriteLine(e);}Console.WriteLine("RESULT passed="+passed+" failed="+failed);return failed==0?0:1;}
}
